import { useState, useEffect, useCallback } from 'react';

function OwnerDashboard({ user }) {
  const [vehicles, setVehicles] = useState([]);
  const [reservations, setReservations] = useState([]);
  const [loading, setLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState(null);

  const load = useCallback(async () => {
    setLoading(true);
    const [vRes, rRes] = await Promise.all([
      fetch('http://localhost:3002/api/vehicles'),
      fetch('http://localhost:3003/api/reservations'),
    ]);
    const vData = await vRes.json();
    const rData = await rRes.json();
    setVehicles(vData.filter((v) => v.ownerId === user.id));
    setReservations(rData);
    setLoading(false);
  }, [user.id]);

  useEffect(() => { load(); }, [load]);

  const myVehicleIds = vehicles.map((v) => v.id);

  const pendingReservations = reservations.filter(
    (r) => r.status === 'pending_approval' && myVehicleIds.includes(r.vehicleId)
  );
  const confirmedReservations = reservations.filter(
    (r) => r.status === 'confirmed' && myVehicleIds.includes(r.vehicleId)
  );

  const getConfirmedRes = (vehicleId) =>
    confirmedReservations.find((r) => r.vehicleId === vehicleId);

  const totalEarnings = confirmedReservations.reduce((sum, r) => sum + r.amount, 0);
  const activeRentals = vehicles.filter((v) => !v.available).length;

  const handleApprove = async (id) => {
    setActionLoading(id + '_approve');
    await fetch(`http://localhost:3003/api/reservations/${id}/approve`, { method: 'PATCH' });
    await load();
    setActionLoading(null);
  };

  const handleReject = async (id) => {
    setActionLoading(id + '_reject');
    await fetch(`http://localhost:3003/api/reservations/${id}/reject`, { method: 'PATCH' });
    await load();
    setActionLoading(null);
  };

  const handleComplete = async (id) => {
    setActionLoading(id + '_complete');
    await fetch(`http://localhost:3003/api/reservations/${id}/complete`, { method: 'PATCH' });
    await load();
    setActionLoading(null);
  };

  if (loading) return <div className="loading">Loading...</div>;

  return (
    <div className="owner-dashboard">
      <h2>My Listings</h2>

      <div className="dash-stats">
        <div className="dash-stat">
          <span className="dash-stat-val">{vehicles.length}</span>
          <span className="dash-stat-label">Total Vehicles</span>
        </div>
        <div className="dash-stat">
          <span className="dash-stat-val">{activeRentals}</span>
          <span className="dash-stat-label">Active Rentals</span>
        </div>
        <div className="dash-stat">
          <span className="dash-stat-val">₺{totalEarnings.toLocaleString()}</span>
          <span className="dash-stat-label">Total Earnings</span>
        </div>
        <div className="dash-stat">
          <span className="dash-stat-val">{pendingReservations.length}</span>
          <span className="dash-stat-label">Pending Approval</span>
        </div>
      </div>

      {pendingReservations.length > 0 && (
        <div className="pending-section">
          <h3 className="pending-section-title">⏳ Pending Approval Requests</h3>
          <div className="pending-list">
            {pendingReservations.map((r) => {
              const vehicle = vehicles.find((v) => v.id === r.vehicleId);
              return (
                <div key={r.id} className="pending-card">
                  <div className="pending-card-info">
                    <div className="pending-card-vehicle">
                      🚗 {vehicle ? `${vehicle.brand} ${vehicle.model}` : `Vehicle #${r.vehicleId}`}
                    </div>
                    <div className="pending-card-meta">
                      <span>👤 {r.renterName}</span>
                      <span>📅 {r.startDate} → {r.endDate}</span>
                      <span>💰 ₺{r.amount}</span>
                      <span className="txid-small">#{r.id}</span>
                    </div>
                  </div>
                  <div className="pending-card-actions">
                    <button
                      className="approve-btn"
                      onClick={() => handleApprove(r.id)}
                      disabled={actionLoading !== null}
                    >
                      {actionLoading === r.id + '_approve' ? '...' : '✓ Approve'}
                    </button>
                    <button
                      className="reject-btn"
                      onClick={() => handleReject(r.id)}
                      disabled={actionLoading !== null}
                    >
                      {actionLoading === r.id + '_reject' ? '...' : '✕ Reject'}
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {vehicles.length === 0 ? (
        <p className="no-vehicles">You have no listings yet.</p>
      ) : (
        <div className="dash-grid">
          {vehicles.map((vehicle) => {
            const res = getConfirmedRes(vehicle.id);
            const isRented = !vehicle.available;

            return (
              <div key={vehicle.id} className={`dash-card ${isRented ? 'rented' : 'available'}`}>
                <div className="dash-card-img">
                  {vehicle.image ? (
                    <img
                      src={vehicle.image.startsWith('http') ? vehicle.image : `/images/${vehicle.image}`}
                      alt={`${vehicle.brand} ${vehicle.model}`}
                      onError={(e) => { e.target.style.display = 'none'; e.target.nextSibling.style.display = 'flex'; }}
                    />
                  ) : null}
                  <div className="vehicle-img-fallback" style={{ display: vehicle.image ? 'none' : 'flex' }}>🚗</div>
                  <div className={`status-pill ${isRented ? 'pill-rented' : 'pill-available'}`}>
                    {isRented ? '🔴 Rented' : '🟢 Available'}
                  </div>
                </div>

                <div className="dash-card-body">
                  <h3>{vehicle.brand} {vehicle.model}</h3>
                  <div className="dash-card-meta">
                    <span className="badge">{vehicle.segment}</span>
                    <span>📍 {vehicle.campus}</span>
                    <span className="price">₺{vehicle.pricePerDay}/day</span>
                  </div>

                  {isRented && res ? (
                    <div className="rental-info">
                      <div className="rental-info-title">📋 Rental Details</div>
                      <div className="rental-info-row">
                        <span>Renter</span>
                        <strong>{res.renterName}</strong>
                      </div>
                      <div className="rental-info-row">
                        <span>Start</span>
                        <strong>{res.startDate}</strong>
                      </div>
                      <div className="rental-info-row">
                        <span>End</span>
                        <strong>{res.endDate}</strong>
                      </div>
                      <div className="rental-info-row">
                        <span>Amount</span>
                        <strong>₺{res.amount}</strong>
                      </div>
                      <div className="rental-info-row">
                        <span>Transaction ID</span>
                        <strong className="txid">{res.transactionId}</strong>
                      </div>
                      <div className="rental-info-row">
                        <span>Reservation No</span>
                        <strong>#{res.id}</strong>
                      </div>
                      <button
                        className="end-rental-btn"
                        onClick={() => handleComplete(res.id)}
                        disabled={actionLoading !== null}
                      >
                        {actionLoading === res.id + '_complete' ? 'Processing...' : '🏁 End Rental'}
                      </button>
                    </div>
                  ) : isRented ? (
                    <div className="rented-no-record">
                      🔴 This vehicle is currently rented.
                    </div>
                  ) : (
                    <div className="available-msg">
                      ✅ This vehicle is ready to rent.
                    </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

export default OwnerDashboard;
